/**
 * @name HomeroRingtone
 * @author SUDOAPT
 * @authorId 0
 * @description Replace the ringtone with Homero's voice
 * @version 1.1.0
 */

const AUDIO_B64 = "";

module.exports = class HomeroRingtone {
  start() {
    this.url = this.makeUrl();
    this.ringUrls = new Set();
    const W = BdApi.Webpack;
    let ok = false;

    // Estrategia 1: parchear createSound/playSound (busca en exports y en exports anidados)
    try {
      const mod = W.getModule(m => m && typeof m.createSound === "function" && typeof m.playSound === "function", { searchExports: true })
        || W.getModule(m => m && typeof m.createSound === "function" && typeof m.playSound === "function");
      if (mod) {
        const isRing = n => typeof n === "string" && /^call_ringing/.test(n);
        BdApi.Patcher.instead("HomeroRingtone", mod, "createSound", (_, args, orig) => isRing(args[0]) ? this.makeSound(args[1]) : orig(...args));
        BdApi.Patcher.instead("HomeroRingtone", mod, "playSound", (_, args, orig) => {
          if (!isRing(args[0])) return orig(...args);
          const s = this.makeSound(args[1]); s.play(); return s;
        });
        ok = true;
      }
    } catch (e) { console.warn("[HomeroRingtone] estrategia 1 falló", e); }

    // Estrategia 2: ubicar las URLs de los call_ringing en los assets de Discord y reemplazarlas al reproducir
    try {
      const ctxs = W.getModule(m => typeof m === "function" && typeof m.keys === "function" && (() => { try { return m.keys().some(k => /call_ringing/.test(k)); } catch { return false; } })(), { searchExports: true, first: false }) || [];
      for (const ctx of [].concat(ctxs)) {
        for (const k of ctx.keys().filter(k => /call_ringing/.test(k))) {
          try { let u = ctx(k); u = typeof u === "string" ? u : u?.default; if (u) this.ringUrls.add(new URL(u, location.href).href); } catch {}
        }
      }
      if (this.ringUrls.size) {
        BdApi.Patcher.before("HomeroRingtone", HTMLMediaElement.prototype, "play", (el) => {
          try {
            if (el.__homero) return;
            if (this.ringUrls.has(new URL(el.currentSrc || el.src, location.href).href)) {
              el.__homero = true;
              const loop = el.loop, vol = el.volume;
              el.src = this.url; el.loop = loop; el.volume = vol;
            }
          } catch {}
        });
        ok = true;
      }
    } catch (e) { console.warn("[HomeroRingtone] estrategia 2 falló", e); }

    if (!ok) BdApi.UI.showToast("HomeroRingtone: no se pudo enganchar el sonido de llamada (Discord cambió su código).", { type: "error" });
  }

  makeUrl() {
    const bin = atob(AUDIO_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return URL.createObjectURL(new Blob([bytes], { type: "audio/mpeg" }));
  }

  makeSound(volume) {
    const audio = new Audio(this.url);
    audio.volume = typeof volume === "number" ? Math.min(1, Math.max(0, volume)) : 0.5;
    const sound = {
      name: "homero_ringtone", audio,
      play() { audio.loop = false; audio.currentTime = 0; audio.play().catch(() => {}); return sound; },
      loop() { audio.loop = true; audio.currentTime = 0; audio.play().catch(() => {}); return sound; },
      pause() { audio.pause(); },
      stop() { audio.pause(); audio.currentTime = 0; },
      mute() { audio.muted = true; }, unmute() { audio.muted = false; },
      setVolume(v) { audio.volume = Math.min(1, Math.max(0, v)); },
      get volume() { return audio.volume; }, set volume(v) { audio.volume = Math.min(1, Math.max(0, v)); },
      destroy() { audio.pause(); audio.src = ""; },
    };
    return sound;
  }

  stop() {
    BdApi.Patcher.unpatchAll("HomeroRingtone");
    if (this.url) URL.revokeObjectURL(this.url);
  }
};
